func Count(insights []Insight) Counts {
	var counts Counts
	for _, insight := range insights {
		switch insight.Severity {
		case SeverityCritical:
			counts.Critical++
		case SeverityWarning:
			counts.Warning++
		default:
			counts.Info++
		}
	}
	return counts
}

